public class E209 {
    static class Box {
        int n;
        Box(int n) { this.n = n; }
    }
    static class Named {
        int n;
        Named(int n) { this.n = n; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Named)) return false;
            return n == ((Named) o).n;
        }
    }
    public static void main(String[] args) {
        Box a = new Box(1), b = new Box(1);
        System.out.println("Box equals: " + a.equals(b));
        Named c = new Named(1), d = new Named(1);
        System.out.println("Named equals: " + c.equals(d));
    }
}
